import styled from 'styled-components';
import { device } from 'utils/media/responsive';
import { ReactComponent as ArrowDown } from 'assets/icons/down-arrow.svg';

export const ArrowDownIcon = styled(ArrowDown)`
  transition: all 0.3s ease;
  transform: ${({ active }) => active ? 'rotate(180deg)' : ''} ;

  @media ${device.tablet1} {
    width: 16px;
    height: 16px;
  }
`;

export const Dropdown = styled.div`
  display: flex;
  cursor: pointer;
  align-items: center;
  justify-content: space-between;
  color: ${({ active }) => (active ? '#181C32' : '#7E8299')};
  position: relative;
  width: 120px;
  height: 48px;
  padding: 0px 12px;
  background-color: #fff;
  border: 1px solid #D0CFCF;
  box-shadow: 0px 4px 16px rgba(34, 37, 48, 0.08);

  @media ${device.tablet1} {
    height: 40px;
    width: 90px;
    padding: 0px 8px;
  }
  @media ${device.tablet} {
    height: 30px;
    width: 90px;
  }
`;

Dropdown.Title = styled.div`
  display: flex;
  align-items: center;
  font-size: 18px;
  font-weight: 400;
  margin-right: 9px;
  @media ${device.tablet1} {
    font-size: 14px;
    margin-right: 5px;
  }
  @media ${device.tablet} {
    font-size: 14px;
    margin-right: 5px;
  }
`;

Dropdown.Menu = styled.ul`
  min-width: 150px;
  position: absolute;
  top: 100%;
  ${({ position }) => (position && position === 'left'
    ? 'left: 0;' : position === 'right' ? 'right: 0;' : 'left: 0;')};
  border-radius: 4px;
  padding: 8px 0;
  margin: 4px 0 0 0;
  list-style: none;
  background-color: #fff;
  box-shadow: 0 6px 12px 0 rgba(73,75,116, 0.16);
  display: ${({ active }) => (active ? 'block' : 'none')};
  z-index: 30;
  margin-top: 20px;
  &::before {
    content: '';
    width: 12px;
    height: 12px;
    background-color: #fff;
    position: absolute;
    top: -10px;
    right: 10%;
    border-top: 1px solid #e5e5e5;
    border-left: 1px solid #e5e5e5;
    transform: rotate(45deg);
  }
  @media ${device.tablet1} {
    min-width: 110px;
  }
  @media ${device.tablet} {
    min-width: 110px;
  }
`;

Dropdown.MenuItem = styled.li`
  cursor: pointer;
  display: flex;
  align-items: center;
  font-weight: 500;
  font-size: 18px;
  color: #181C32;
  line-height: 18px;
  padding: 10px 12px;
  white-space: nowrap;
  transition: .2s ease-in;
  &:hover {
    background-color: #F8F8F8;
  }
  @media ${device.tablet} {
    font-size: 14px;
    line-height: 12px;
    padding: 6px;
  }
`;
